/**
 * Local catalog snapshot sourced from AniList (public GraphQL API, no key
 * needed — see PRD R2).
 *
 * The data lives in `catalog.data.json` and is regenerated by
 * `npm run catalog` (scripts/build-catalog.mjs). Don't hand-edit the JSON —
 * every field comes from that script, including each season's own AniList
 * `mediaId`, which is what playback resolution maps to a provider.
 *
 * Posters, banners and episode thumbnails are remote URLs (AniList CDN and
 * streaming-provider images). They're demo assets under the same licensing
 * caveat as before — swap for owned art before production (PRD R1).
 */
import type { Title } from "@/lib/types";
import data from "@/lib/catalog.data.json";

export const catalog = data as Title[];

export function allGenres(): string[] {
  const set = new Set<string>();
  for (const t of catalog) {
    for (const g of t.genres) set.add(g);
  }
  return Array.from(set).sort();
}
